fast_pseudocode:
# After (regressed): block_size=128, num_stages=2, waves/SM=3.39
@triton.autotune(configs=[Config(BLOCK_SIZE=128, num_warps=4, num_stages=2), ...], key=['N'])
def kernel(...):
    for off in range(0, N, BLOCK_SIZE):
        x = tl.load(..., eviction_policy='evict_last')
        # Sum-of-squares Welford: more instructions generated
        new_sum = sum(x)
        new_sum2 = sum(x*x)
        new_mean = new_sum / count
        new_m2 = new_sum2 - new_sum * new_mean

